package main

import (
	"context"
	"flag"
	"os"
	"os/signal"

	"legagent/app/services"
)

// runImportCouncilRules 把 data/council_rules/council_rules.json 寫入 public.council_rules。
//
//	go run . import-council-rules
//
// @ai:generated by=claude-opus-5-5 date=2026-11-05
// @ai:purpose 規則內容由人審閱並入版控，這個指令把審閱後的版本同步到資料庫
// @ai:input args 子命令參數
// @ai:output none
// @ai:sideeffect 建立並覆寫 public.council_rules、失敗時 os.Exit
func runImportCouncilRules(args []string) {
	fs := flag.NewFlagSet("import-council-rules", flag.ExitOnError)
	cfgPath := fs.String("config", defaultConfigPath, "config.yaml 路徑")
	file := fs.String("file", "data/council_rules/council_rules.json", "規則 JSON 路徑")
	_ = fs.Parse(args)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	cfg, log := mustLoad(*cfgPath)
	set, err := services.LoadCouncilRules(*file)
	if err != nil {
		log.Error("load council rules failed", "path", *file, "err", err)
		os.Exit(1)
	}
	db := mustOpenDB(cfg, log)
	defer db.Close()

	count, err := services.NewCouncilRulesService(db, log).Import(ctx, set)
	if err != nil {
		db.Close()
		os.Exit(1)
	}
	log.Info("import done", "rules", count, "reviewed_on", set.ReviewedOn)
}
